pub unsafe extern "C" fn grTFox_80220E5C(arg0: i32) -> *mut DynamicsDesc {
    melee_core::ct!("grTFox_80220E5C");
    if arg0 != -1 {
        let mut i = ext::mpJointFromLine(arg0);
        if i != -1 && i == 1 {
            i = ext::mpLineGetKind(arg0);
            if i == CollLine_Floor as i32 {
                return (*YAKUMONO_PARAM.load(Ordering::Relaxed)).unk0 as *mut DynamicsDesc;
            }
            if i == CollLine_Ceiling as i32 {
                return (*YAKUMONO_PARAM.load(Ordering::Relaxed)).unk4 as *mut DynamicsDesc;
            }
            if i == CollLine_RightWall as i32 {
                return (*YAKUMONO_PARAM.load(Ordering::Relaxed)).unk8 as *mut DynamicsDesc;
            }
            if i == CollLine_LeftWall as i32 {
                return (*YAKUMONO_PARAM.load(Ordering::Relaxed)).unkC as *mut DynamicsDesc;
            }
            return null_mut();
        }
    }
    null_mut()
}

